// ---- Roblox DataTypes ----
public struct Vector2
{
    public float X { get; set; }
    public float Y { get; set; }
    public float Magnitude { get; set; }
    public Vector2 Unit => default!;
    public Vector2(float x, float y) { X = x; Y = y; Magnitude = default; }
    public float Dot(Vector2 other) => default!;
    public Vector2 Lerp(Vector2 to, float alpha) => default!;
}

public struct Vector3
{
    public float X { get; set; }
    public float Y { get; set; }
    public float Z { get; set; }
    public float Magnitude { get; set; }
    public Vector3 Unit => default!;
    public Vector3(float x, float y, float z) { X = x; Y = y; Z = z; Magnitude = default; }
    public float Dot(Vector3 other) => default!;
    public Vector3 Cross(Vector3 other) => default!;
    public Vector3 Lerp(Vector3 to, float alpha) => default!;
}

public struct CFrame
{
    public Vector3 Position { get; set; }
    public Vector3 LookVector { get; set; }
    public Vector3 RightVector { get; set; }
    public Vector3 UpVector { get; set; }
    public CFrame(float x, float y, float z) { Position = default; LookVector = default; RightVector = default; UpVector = default; }
    public CFrame(Vector3 position) { Position = position; LookVector = default; RightVector = default; UpVector = default; }
    public CFrame Inverse() => default!;
    public CFrame Lerp(CFrame to, float alpha) => default!;
    public Vector3 PointToWorldSpace(Vector3 v) => default!;
}

public struct Color3
{
    public float R { get; set; }
    public float G { get; set; }
    public float B { get; set; }
    public Color3(float r, float g, float b) { R = r; G = g; B = b; }
    public Color3 Lerp(Color3 to, float alpha) => default!;
}

public struct UDim
{
    public float Scale { get; set; }
    public int Offset { get; set; }
    public UDim(float scale, int offset) { Scale = scale; Offset = offset; }
}

public struct UDim2
{
    public UDim X { get; set; }
    public UDim Y { get; set; }
    public UDim2(float xScale, int xOffset, float yScale, int yOffset) { X = default; Y = default; }
    public UDim2 Lerp(UDim2 to, float alpha) => default!;
}

public struct Rect
{
    public Vector2 Min { get; set; }
    public Vector2 Max { get; set; }
    public float Width { get; set; }
    public float Height { get; set; }
    public Rect(Vector2 min, Vector2 max) { Min = min; Max = max; Width = default; Height = default; }
}

public struct Region3
{
    public Vector3 CFrame { get; set; }
    public Vector3 Size { get; set; }
    public Region3(Vector3 min, Vector3 max) { CFrame = default; Size = default; }
}

public struct NumberRange
{
    public float Min { get; set; }
    public float Max { get; set; }
    public NumberRange(float value) { Min = value; Max = value; }
    public NumberRange(float min, float max) { Min = min; Max = max; }
}

public struct BrickColor
{
    public string Name { get; set; }
    public Color3 Color { get; set; }
    public int Number { get; set; }
    public BrickColor(int number) { Name = default!; Color = default; Number = number; }
}

public struct TweenInfo
{
    public float Time { get; set; }
    public int RepeatCount { get; set; }
    public bool Reverses { get; set; }
    public TweenInfo(float time) { Time = time; RepeatCount = default; Reverses = default; }
}

public struct Ray
{
    public Vector3 Origin { get; set; }
    public Vector3 Direction { get; set; }
    public Ray(Vector3 origin, Vector3 direction) { Origin = origin; Direction = direction; }
